css:
:root{
  --green-900:#122f22;
  --green-800:#183a2a;
  --green-700:#1f4a35;
  --green-600:#2e7d4f;
  --green-500:#3a9d63;
  --gold:#e0a72e;
  --gold-dark:#c8901f;
  --gold-soft:rgba(224,167,46,.14);
  --lime:#e0a72e;
  --lime-dark:#c8901f;
  --ink:#16241c;
  --body:#33413a;
  --muted:#6b7b72;
  --bg:#f6f8f4;
  --card:#ffffff;
  --line:#e3ebe3;
  --ring:rgba(46,125,79,.35);
  --shadow:0 10px 30px rgba(18,47,34,.10);
  --shadow-sm:0 2px 10px rgba(18,47,34,.06);
  --radius:16px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0;
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Inter,Roboto,Helvetica,Arial,sans-serif;
  color:var(--body);
  background:var(--bg);
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
}
a{color:inherit;text-decoration:none}
img{max-width:100%;display:block}
h1,h2,h3{color:var(--ink);line-height:1.15;margin:0 0 .5em;font-weight:800;letter-spacing:-.02em}
h2{font-size:clamp(1.6rem,3.4vw,2.4rem)}
h3{font-size:1.15rem;font-weight:750}
p{margin:0 0 1rem}
.wrap{max-width:1160px;margin:0 auto;padding:0 22px}
.section{padding:76px 0}
.eyebrow{display:inline-block;font-size:.78rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--gold-dark);background:var(--gold-soft);padding:6px 12px;border-radius:999px;margin-bottom:16px}
.lead{font-size:1.08rem;color:var(--muted);max-width:60ch}

/* buttons */
.btn{display:inline-flex;align-items:center;gap:.5rem;font-weight:700;font-size:.98rem;padding:13px 22px;border-radius:12px;border:1px solid transparent;cursor:pointer;transition:transform .12s ease,box-shadow .12s ease,background .12s ease;white-space:nowrap}
.btn:active{transform:translateY(1px)}
.btn-primary{background:var(--green-600);color:#fff;box-shadow:0 6px 16px rgba(46,125,79,.28)}
.btn-primary:hover{background:var(--green-700)}
.btn-lime{background:var(--lime);color:#173d1f}
.btn-lime:hover{background:var(--lime-dark)}
.btn-ghost{background:#fff;color:var(--ink);border-color:var(--line)}
.btn-ghost:hover{border-color:var(--green-500);color:var(--green-700)}
.btn-block{width:100%;justify-content:center}

/* header */
header.site{position:sticky;top:0;z-index:50;background:rgba(246,248,244,.86);backdrop-filter:saturate(140%) blur(10px);border-bottom:1px solid var(--line)}
.nav{display:flex;align-items:center;justify-content:space-between;min-height:104px;gap:16px;padding:10px 0}
.brand{display:flex;align-items:center;gap:10px;font-weight:800;color:var(--ink);font-size:1.05rem}
.brand .logo{height:84px;width:auto}
@media(max-width:560px){.brand .logo{height:66px}.nav{min-height:88px}}
.brand .mark{width:34px;height:34px;border-radius:9px;background:linear-gradient(135deg,var(--green-600),var(--green-500));display:grid;place-items:center;color:#fff;font-weight:900}
.nav-actions{display:flex;align-items:center;gap:12px}
.nav-phone{font-weight:800;color:var(--green-700);display:flex;align-items:center;gap:7px}
@media(max-width:640px){.nav-phone span.lbl{display:none}}

/* breadcrumb */
.crumb{background:#efeee4;border-bottom:1px solid var(--line);font-size:.85rem}
.crumb .wrap{padding:11px 22px}
.crumb a{color:var(--green-700);font-weight:700}
.crumb a:hover{color:var(--gold-dark)}
.crumb .sep{margin:0 9px;color:#b3bcae}
.crumb .cur{color:var(--muted)}

/* hero (dark photo overlay) */
.hero{position:relative;color:#fff;background-color:var(--green-900);background-size:cover;background-position:center;overflow:hidden}
.hero::before{content:"";position:absolute;inset:0;background:linear-gradient(115deg,rgba(11,29,18,.90) 0%,rgba(13,36,22,.70) 45%,rgba(15,42,26,.42) 100%);z-index:0}
.hero .wrap{position:relative;z-index:1;padding:66px 22px 74px}
.hero-inner{max-width:760px}
.hero .eyebrow{color:var(--gold);background:rgba(224,167,46,.16)}
.hero h1{font-size:clamp(2.3rem,5.6vw,3.6rem);color:#fff;margin-bottom:.15em}
.hero h1 .accent{color:var(--gold)}
.hero .sub{font-size:1.24rem;color:#eef4ee;font-weight:600;margin:.1rem 0 .7rem}
.hero .body{font-size:1.03rem;color:#d7e4da;max-width:60ch}
.hero-cta{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0 6px}
.hero-mini{color:#c9dccf;font-size:.9rem;font-weight:600;margin-top:8px}
.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:30px;max-width:860px}
@media(max-width:700px){.stats{grid-template-columns:1fr 1fr}}
.stat{background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.20);border-radius:14px;padding:16px 12px;text-align:center;backdrop-filter:blur(2px)}
.stat .num{font-size:1.75rem;font-weight:900;color:var(--gold);line-height:1}
.stat .lbl{font-size:.7rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:#dce8de;margin-top:7px}
.btn-outline{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn-outline:hover{background:rgba(255,255,255,.14);border-color:#fff}

/* form card */
.form-card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);padding:26px}
.form-card h3{font-size:1.35rem;margin-bottom:2px}
.form-card .fsub{color:var(--muted);font-size:.95rem;margin-bottom:16px}
.field{margin-bottom:13px}
.field label{display:block;font-size:.82rem;font-weight:700;color:var(--ink);margin-bottom:5px}
.field input,.field select,.field textarea{width:100%;padding:11px 13px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:.95rem;color:var(--ink);background:#fbfdfa;transition:border-color .12s,box-shadow .12s}
.field input:focus,.field select:focus,.field textarea:focus{outline:none;border-color:var(--green-500);box-shadow:0 0 0 4px var(--ring)}
.field textarea{min-height:84px;resize:vertical}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:13px}
@media(max-width:520px){.grid-2{grid-template-columns:1fr}}
.reassure{display:flex;align-items:center;gap:8px;justify-content:center;color:var(--muted);font-size:.82rem;font-weight:600;margin-top:12px}

/* services */
.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
@media(max-width:1000px){.cards{grid-template-columns:repeat(2,1fr)}}
@media(max-width:560px){.cards{grid-template-columns:1fr}}
.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:22px;box-shadow:var(--shadow-sm);transition:transform .14s ease,box-shadow .14s ease}
.card:hover{transform:translateY(-3px);box-shadow:var(--shadow)}
.card .ico{width:44px;height:44px;border-radius:11px;background:rgba(46,125,79,.12);display:grid;place-items:center;margin-bottom:14px;font-size:1.3rem}
.card p{font-size:.93rem;color:var(--body);margin:0}
.card.photo{padding:0;overflow:hidden;display:flex;flex-direction:column}
.card.photo .card-media{position:relative;aspect-ratio:16/11;overflow:hidden;background:#e8efe8}
.card.photo .card-media img{width:100%;height:100%;object-fit:cover;transition:transform .3s ease}
.card.photo:hover .card-media img{transform:scale(1.05)}
.card.photo .card-body{padding:18px 20px 22px}
.card.photo .card-body h3{margin-bottom:6px}
.services-sec{position:relative;overflow:hidden}
.services-sec .wmk{position:absolute;top:-40px;right:-60px;width:340px;opacity:.06;pointer-events:none;z-index:0}
.services-sec .wrap{position:relative;z-index:1}

/* cta band */
.cta-band{position:relative;min-height:340px;display:flex;align-items:center;color:#fff;background-size:cover;background-position:center;background-color:var(--green-800)}
.cta-band::before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(12,32,20,.82),rgba(12,32,20,.45))}
.cta-band .wrap{position:relative;z-index:1;max-width:700px}
.cta-band h2{color:#fff;font-size:clamp(1.7rem,3.6vw,2.5rem)}
.cta-band p{color:#dbeede;font-size:1.05rem;max-width:52ch}
.cta-band .hero-cta{margin-top:18px}

/* why image */
.why-head{display:grid;grid-template-columns:1.3fr .9fr;gap:34px;align-items:center;position:relative;z-index:1}
@media(max-width:820px){.why-head{grid-template-columns:1fr}}
.why-head .why-img img{border-radius:18px;box-shadow:var(--shadow);width:100%;aspect-ratio:4/3;object-fit:cover}
.why{position:relative;overflow:hidden}
.why .wmk{position:absolute;bottom:-50px;left:-50px;width:320px;opacity:.07;pointer-events:none;z-index:0}
.why .wrap{position:relative;z-index:1}

/* pricing */
.pricing-wrap{display:grid;grid-template-columns:1.35fr .9fr;gap:34px;align-items:start}
@media(max-width:900px){.pricing-wrap{grid-template-columns:1fr}}
.table-card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow-sm);overflow:hidden}
table{width:100%;border-collapse:collapse;font-size:.92rem}
thead th{background:var(--green-800);color:#fff;text-align:left;padding:13px 16px;font-size:.78rem;letter-spacing:.04em;text-transform:uppercase}
tbody td{padding:13px 16px;border-top:1px solid var(--line);vertical-align:top}
tbody tr:nth-child(even){background:#fafcf8}
td.proj{font-weight:700;color:var(--ink)}
td.price{color:var(--gold-dark);font-weight:700;white-space:nowrap}
.price-side .box{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:22px;box-shadow:var(--shadow-sm);margin-bottom:18px}
.price-side ul{margin:0;padding-left:18px}
.price-side li{margin-bottom:9px;font-size:.93rem}
.promise{background:var(--green-800);color:#eafcef;border-radius:var(--radius);padding:22px}
.promise strong{color:#fff}
.promise a{color:var(--lime);font-weight:800;text-decoration:underline}

/* why us */
.why{background:linear-gradient(180deg,#eef3ea,var(--bg))}
.why-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:14px}
@media(max-width:820px){.why-grid{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.why-grid{grid-template-columns:1fr}}
.why-item{background:#fff;border:1px solid var(--line);border-radius:14px;padding:20px;box-shadow:var(--shadow-sm)}
.why-item h3{font-size:1.02rem;margin-bottom:5px}
.why-item p{font-size:.92rem;color:var(--body);margin:0}
.check{color:var(--gold-dark);font-weight:900;margin-right:6px}

/* zones */
.zones{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:12px}
@media(max-width:820px){.zones{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.zones{grid-template-columns:1fr}}
.zone{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:20px;box-shadow:var(--shadow-sm)}
.zone h3{font-size:1rem;color:var(--green-700);margin-bottom:6px}
.zone p{font-size:.9rem;margin:0;color:var(--body)}
.zone.cta-zone{background:var(--green-700);color:#eafcef;display:flex;flex-direction:column;justify-content:center;gap:12px}
.zone.cta-zone h3{color:#fff}
.zone.cta-zone a.btn{align-self:flex-start}

/* faq */
.faq-list{max-width:860px;margin:14px auto 0}
details{background:var(--card);border:1px solid var(--line);border-radius:12px;margin-bottom:12px;box-shadow:var(--shadow-sm);overflow:hidden}
details[open]{border-color:var(--green-500)}
summary{cursor:pointer;list-style:none;padding:17px 52px 17px 20px;font-weight:750;color:var(--ink);position:relative;font-size:1rem}
summary::-webkit-details-marker{display:none}
summary::after{content:"+";position:absolute;right:20px;top:50%;transform:translateY(-50%);font-size:1.4rem;font-weight:700;color:var(--gold-dark);transition:transform .2s}
details[open] summary::after{content:"\2013"}
.faq-a{padding:0 20px 18px;color:var(--body);font-size:.95rem}

/* footer */
footer.site{background:var(--green-900);color:#c9dccf;padding:60px 0 34px;margin-top:20px}
footer.site a:hover{color:#fff;text-decoration:underline}
.foot-top{display:grid;grid-template-columns:1.4fr 1fr 1fr 1.2fr;gap:30px}
@media(max-width:860px){.foot-top{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.foot-top{grid-template-columns:1fr}}
footer.site h4{color:#fff;font-size:.82rem;letter-spacing:.1em;text-transform:uppercase;margin:0 0 14px}
footer.site ul{list-style:none;margin:0;padding:0}
footer.site li{margin-bottom:9px;font-size:.92rem}
.foot-brand img{height:84px;margin-bottom:14px;background:#fff;padding:8px 12px;border-radius:10px}
.foot-brand p{font-size:.9rem;color:#a9c3b1}
.foot-phone{color:#fff;font-weight:800;font-size:1.15rem;margin:8px 0 2px;display:inline-block}
.subs{font-size:.85rem;color:#9fbaa7;line-height:1.9;margin-top:6px}
.foot-bottom{border-top:1px solid rgba(255,255,255,.12);margin-top:34px;padding-top:20px;display:flex;flex-wrap:wrap;gap:16px;justify-content:space-between;align-items:center;font-size:.82rem;color:#9fbaa7}
.foot-bottom .fcta{display:flex;gap:10px}
.local-links{margin-top:14px;font-size:.85rem}
.local-links a{color:#bcd6c4;text-decoration:underline}

/* modal */
.modal-overlay{position:fixed;inset:0;background:rgba(12,26,18,.62);backdrop-filter:blur(3px);display:none;align-items:flex-start;justify-content:center;padding:5vh 18px;z-index:100;overflow-y:auto}
.modal-overlay.open{display:flex}
.modal{background:var(--card);border-radius:var(--radius);box-shadow:0 24px 60px rgba(0,0,0,.35);width:100%;max-width:520px;position:relative;padding:28px 26px 24px;animation:pop .2s ease}
@keyframes pop{from{opacity:0;transform:translateY(10px) scale(.98)}to{opacity:1;transform:none}}
.modal h3{font-size:1.4rem;margin:0;padding-right:44px}
.modal .fsub{color:var(--muted);font-size:.95rem;margin:4px 0 16px}
.modal-close{position:absolute;top:14px;right:14px;width:38px;height:38px;border-radius:10px;border:1px solid var(--line);background:#fff;font-size:1.4rem;line-height:1;color:var(--muted);cursor:pointer;display:grid;place-items:center;transition:background .12s,color .12s}
.modal-close:hover{background:#f3f6f1;color:var(--ink)}
body.no-scroll{overflow:hidden}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);border:0}

